quests[10698] = { id = 10698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets" }
quests[10699] = { id = 10699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet" }
quests[10700] = { id = 10700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets" }
quests[10701] = { id = 10701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Down Netherock", description = "To whomever cares about the timely construction of the X-52 Nether-Rocket --\n\nThe king of the local mountain giants, Netherock, has been terrorizing the Crumbling Wastes.  He's been interfering with operations all along the south ledge of the island!\n\nTake your friends and deal with him!  Then, return to me here in Area 52.\n\nRocket-Chief Fuselage", sourceObjective = "Slay Netherock and then report in with Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "What?  What?!  Be quick about it... there's so much to do around here.\n\nI want to get this thing off the ground some day, you know?", completion = "Oh!  Oh... you took care of Netherock.  Good news that!\n\nWith that troublesome mountain giant out of the picture, we should have an easier time of exploi... er, husbanding the resources of the Crumbling Wastes.\n\nGlad to hear that those poor, innocent elementals down there won't be getting squished by him.\n\nHow ever can I repay you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10702] = { id = 10702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grunt's Work...", description = "All Horde forces in this region have been dispatched to handle the attacks from the Burning Legion. This means that we are short-handed for grunt work.\n\nOur supply caravans are in constant danger from the wildlife of the region. We can't veer 15 feet off the road without running into a chimaera, felboar, or abnormally large scorpion.\n\nGet out there and clear Shadowmoon Valley of its sadistic wildlife! Just kill 'em all!", sourceObjective = "Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.\n\nThese creatures include Felboars, Vilewing Chimaera, and Scorchshell Pincer. Any combination will be sufficient.", progress = "Return to me when the wilds are safe for our caravans to traverse.", completion = "Fantastic! Should I have any other grunt work that needs to be done, I'll find you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10703] = { id = 10703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put On Yer Kneepads...", description = "It's time to get down in the muck and get dirty. What were you expectin'? You gotta learn to walk before you can crawl, right? Er, reverse that...\n\nAnyway, we got all hands on deck fer killin' the garbage being thrown at us by the Burning Legion. That leaves you with the honor of cleaning up the crazed wildlife of Shadowmoon Valley.\n\nGrab a sword, staff, whatever it is that makes you happy, and kill as much of the wildlife as you can see. That'll clear a way out for our supply caravans!", sourceObjective = "Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.\n\nThese creatures include Felboars, Vilewing Chimaeras, and Scorchshell Pincers. Any combination will be sufficient.", completion = "Aye, good work! Here's some coin for your efforts. If we be needin' more garbage taken out, I'll know who to call.", sourceObjectiveStatus = "unverified-source-field" }
quests[10704] = { id = 10704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Break Into the Arcatraz", description = "A message was embedded in the ata'mal crystal that you recovered.  Nexus-Prince Haramad has given us information vital to our campaign against Tempest Keep.\n\nHe tells us that there are two pieces, shards to a key, which, when combined, will unlock the keep's Arcatraz satellite.\n\nOne half is possessed by an ancient in the Botanica known as Warp Splinter.  The other is held by Pathaleon the Calculator inside the Mechanar.\n\nBring both shards to me and I will combine them into the Arcatraz key.", sourceObjective = "A'dal has tasked you with the recovery of the Top and Bottom Shards of the Arcatraz Key. Return them to him, and he will fashion them into the Key to the Arcatraz for you.", progress = "<A'dal's voice vibrates melodically through your mind.>\n\nYou have returned.  Do you bring with you the two shards of the Arcatraz key?", completion = "I am impressed, {name}, though I should expect nothing less of the hero who returned the ata'mal crystal to us.\n\nGive over the two shards and I will see to it that they are combined into their final form.  Then you will have access to the Arcatraz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10705] = { id = 10705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seer Udalo", description = "I hope you're not shocked when I reveal to you that the pieces of the Medallion of Karabor you obtained from my minions are mere replicas.\n\n<Akama shows you an identical medallion in his open palm.>\n\nMy Deathsworn and I have kept the secret from Illidan for as long as possible.   We are however, still missing the final piece.\n\nUdalo came to me in dreams  to announce he had found it.  Unfortunately he is held by Kael'thas inside the Arcatraz in Tempest Keep.  Find him and see what he knows.", sourceObjective = "Find Seer Udalo inside the Arcatraz in Tempest Keep.", completion = "The Ashtongue Seer has been long dead.  As you turn over his body, you spot writing scrawled on the floor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10706] = { id = 10706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Portent", description = "Before he died, Udalo appears to have written a single word on the floor beneath him.  The writing is barely legible but you recognize the word Atam'al.\n\nPerhaps Akama will understand the meaning of his brethren's message.", sourceObjective = "Return to Akama at the Warden's Cage in Shadowmoon Valley.", completion = "Yes... of course!  It all becomes clear now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10707] = { id = 10707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ata'mal Terrace", description = "It has been known to us that the fel orcs, under Illidan's command, have guarded an Ata'mal crystal known as the Heart of Fury at the Ata'mal Terrace.  They cloud its presence with dark magic, to keep it from the Sha'tar.\n\nFight your way to the Ata'mal Terrace outside the Black Temple and turn your eyes to the sky.  Shadowlord Deathwail will circle the terrace, beyond your reach.  You will have to slay him and his warlocks before you can obtain the crystal.\n\nIt won't be easy, {name}.  I wish you luck.", sourceObjective = "Go to the top of the Ata'mal Terrace in Shadowmoon Valley and obtain the Heart of Fury. Return to Akama at the Warden's Cage in Shadowmoon Valley when you've completed this task.", progress = "You've returned, {name}.", completion = "The crystal!  Its power... now in my hands!", sourceObjectiveStatus = "unverified-source-field" }
quests[10708] = { id = 10708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.You will be able to choose one of these rewards:", sourceObjective = "Bring the Medallion of Karabor to A'dal in Shattrath City.<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}. Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side. Take it to the one being we know we can trust with its power. Take the medallion to A'dal in Shattrath City.You will be able to choose one of these rewards:", sourceObjectiveStatus = "unverified-source-field" }
quests[10709] = { id = 10709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunion", description = "So you come from the world beyond the Portal? And you know of Rexxar. Oh yes, I am quite familiar with him.\n\nYou see, he is my son.\n\nBut he made his choice a lifetime ago. He is not one of us, and he is not welcome here. We have enough troubles with the Bloodmaul ogres.\n\nKnow this: being born a half-breed does not make you Mok'Nathal.", sourceObjective = "Speak with Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", completion = "So my father does live. I did not expect him to forgive - that was never his way. But I had hoped that the years had dulled the anger he must have felt at my departure.\n\nThirty years ago, I left the Mok'Nathal to follow the Horde to Azeroth. Leoroxx was staunchly against it, but then, he never gave me any reason to stay. Still, I had hoped for a better welcome than this.\n\nHe wanted a Mok'Nathal for a son and he has one now, even if he will not know it.\n\nI must open his eyes.", sourceObjectiveStatus = "unverified-source-field" }
quests[10710] = { id = 10710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: The Singing Ridge", description = "I've been fiddling with the Zephyrium Capicitorium and I'm ready to perform another test!  Do you want to help?\n\nThis next flight should be short, but fast!\n\nUm... and although I'm sure there's no danger... I have this, uh, waiver that I'd like  you to sign.  It's just a formality, I assure you!\n\nBest of luck!  Talk to Rally to launch yourself, and come back to me after the experiment is over!", sourceObjective = "Sign Tally's Waiver, then speak with Rally Zapnabber to use the Zephyrium Capacitorium.", progress = "Don't worry, {name}!  Worry never got anyone anywhere!", completion = "Wow!  Again, you survived!  I'm a much better engineer than I give myself credit for!\n\nHere's your pay!  And check back with me later... I'll have more experiments that'll need more test subjects!", sourceObjectiveStatus = "unverified-source-field" }
quests[10711] = { id = 10711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: Razaan's Landing", description = "{name}, I raised the efficiency of the Zephyrium Capacitorium by 30 percent.  That will launch a test subject of your weight and wind drag ratio to new heights!  Want to test my theory?  This experiment ought to send you near Razaan's Landing.\n\nSpeak with Rally... he'll get you prepared for launch.", sourceObjective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium.", progress = "What?  You don't want to perform the experiment?  Don't fret, {name}!  I'm behind you all the way!", completion = "Oh, gosh!  You're back so soon!  I saw you take off and you shot up like a rocket!  I was sure it would take at least a month of convalescing to mend the broken legs from that flight!  You're tough, and brave, and foolhardy!  But mostly... you're brave!", sourceObjectiveStatus = "unverified-source-field" }
quests[10712] = { id = 10712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: Ruuan Weald", description = "Hey, {name}.  I'm glad I caught you!  I have a very important mission!\n\nHere is a nether-weather vane.  I need you to take some in flight readings for me and deliver them to my cousin in Ruuan Weald.\n\nSpeak with Rally and take a Zephyrium Capacitorium flight to Ruuan Weald.  While you're flying, spin the vane!\n\nAfter you land, bring the spinning vane to O'Mally Zabnabber.\n\nGood luck, {name}.  And don't delay!", sourceObjective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium. While flying to Ruuan Weald, spin the Nether-weather Vane. Deliver the Spinning Nether-weather Vane to O'Mally Zapnabber in Evergrove.", progress = "Hello hello!  My clo-... I mean, my cousin Tally told me you'd be dropping in.  Do you have something for me?", completion = "Oh, you took readings from the nether-weather vane?  Splendid!  The data gained from this instrument -- coupled with my measurements of druid magic -- will bear much fruit!\n\nOh, the applications will boggle the mind, I assure you!", sourceObjectiveStatus = "unverified-source-field" }
quests[10713] = { id = 10713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...and a Time for Action", description = "We will not stand idly by while they decimate the Ruuan Weald around us.  Our first priority must be to the trees.\n\n{class}, I want you to go back out into the Weald and deliver a very different message for us.  I want you to slay every one of their hewers that you come into contact with!\n\nIf they will not listen to reason, perhaps they will listen to a more assertive method of persuasion!", sourceObjective = "Slay 10 Wyrmcult Hewers.", progress = "Have you protected the trees?  Are the hewers cut down?", completion = "Thank you, {name}.\n\nWhile we'll see to it that the wildlife will replenish itself in quick order, regrowing the trees, especially in a natural fashion, is a much more time-intensive process.", sourceObjectiveStatus = "unverified-source-field" }
quests[10714] = { id = 10714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Spirit's Wings", description = "If the Mok'Nathal are tormented by the Bloodmaul ogres, then I will stop them and their followers. Ogres are simple creatures, and there is little profit they could gain from harassing the Mok'Nathal.\n\nThere must be something more to this. {name}, take Spirit, my hawk, and spy upon the conversations of the Bloodmaul's leaders. He may go undetected where we cannot.", sourceObjective = "Find a Bloodmaul Taskmaster and a Bloodmaul Soothsayer engaged in conversation, then use Rexxar's Whistle to summon Spirit to spy on them.", progress = "What have you learned, {name}?", completion = "<Spirit perches upon Rexxar's shoulder while Rexxar listens intently.>\n\nSo it is the sons of Gruul that are behind the ogres' actions. They command the Bloodmaul ogres to destroy the Mok'Nathal to gain their favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10715] = { id = 10715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Churning Gulch", description = "So, your Rexxar would have me fashion a poison for him? I'll give him what he desires, but there will be a price. Even for friends, there must be a price. Free things destroy friendships.\n\nFirst, you must venture a short distance to the southwest to the Churning Gulch.\n\nTherein mill some of the most poisonous creatures in all of Outland, or anywhere. I speak of the crust bursters, and this poison will require gathering their glands for me.", sourceObjective = "Collet 7 Crust Burster Venom Glands.", progress = "You have all of the venom glands? If not, begone and waste no more of my time until you do.", completion = "Very well.  A simple, if mundane, task has been completed. Now, hand me the glands and I will do the difficult part.", sourceObjectiveStatus = "unverified-source-field" }
quests[10716] = { id = 10716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: Raven's Wood <needs reward>", description = "The Zephyrium Capacitorium is ready for its longest launch yet!  What do you say, {name}?  Do you want to fly one more time?\n\nI've been boosting the proplusion system but, until I get all the variables hammered out, the capicitorium will need added fuel to give it the necessary kick!  Speak with Rally before the flight -- he has the details.\n\nBest of luck, {name}.  This flight will take you to distant Raven's Wood.  If you survive the flight -- and the wood's ogres and arakkoa -- come back and we'll celebrate!", sourceObjective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station.", sourceObjectiveStatus = "unverified-source-field" }
quests[10717] = { id = 10717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poaching from Poachers", description = "Pardon me, but I couldn't help but overhear your conversation with Chawn.  I'd like to help.\n\nI'm studying the Blackwing Coven, and helping the druids in their dealings with them.\n\nI am very interested in acquiring a few of their dragon whelps; it would help us to gauge exactly what we're up against by understanding that which they revere.\n\nBut first, we're going to need to acquire some nets.  I noticed that the wyrmcult poachers out in the Ruuan Weald have an abundance of them.", sourceObjective = "Collect 5 Wyrmcult Nets.", progress = "How's the procurement of nets coming along?  From what I've seen, those nets that the poachers use should be strong enough for the task at hand.", completion = "Oh, those look splendid.  These cultists certainly have an eye for craftsmanship.\n\nToo bad for them that it's misdirected.\n\nAnd now that we have the nets, would you be willing to help little old me with a thing or two?", sourceObjectiveStatus = "unverified-source-field" }
quests[10718] = { id = 10718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits Have Voices", description = "{name}, now that you can see me, there is something you must tell Rexxar. I know that he seeks his people, and I know where they are.\n\nThe Mok'Nathal, as they are known, have a village to the east beyond the Razor Ridge.\n\nGo, give Rexxar this news. His people are in danger, and I know that he will want to come to their aid.", sourceObjective = "Speak with Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", completion = "What is this you speak of?\n\nGarm Wolfbrother? He was the last chieftain of the Thunderlord clan. If you have communed with his spirit, then it must be true.", sourceObjectiveStatus = "unverified-source-field" }
quests[10719] = { id = 10719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did You Get The Note?", description = "The cultist dropped this note, which apparently was to be delivered to Overseer Nuaar.  It is signed by someone named Kolphis Darkscale.\n\nIt is likely that Tree Warden Chawn will be interested in looking at this.", sourceObjective = "Deliver the Meeting Note to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains.", progress = "What's that you have there?  Is that a blood stain on that note?", completion = "This is interesting, but disturbing.  I wonder if Samia knows who this Kolphis Darkscale is?", sourceObjectiveStatus = "unverified-source-field" }
quests[10720] = { id = 10720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smallest Creatures", description = "The ogres, simple as they are, would notice you dispersing this poison throughout their camp. Thus, I will teach you how to enlist the help of one of nature's smallest creatures to do this task.\n\nBy playing a simple rhythm on this drum, you can coax a marmot to follow your commands.\n\nThere is a den of marmots near the Bloodmaul camp, to the north, down in the Daggermaw Canyon past the Circle of Blood.\n\nOnce you have a marmot's aid, use it to disperse the poison to the Bloodmaul's kegs.", sourceObjective = "Use the Kodohide Drum at the Marmot Den. While controlling the Marmot, poison the three kegs in the Bloodmaul Camp.", progress = "Is it done?", completion = "For many long years I have concentrated my efforts on perfecting the ways of communicating with nature. This is but a small part of the untapped potential that beasts can bring to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10721] = { id = 10721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boaring Time for Grulloc", description = "{name}, I have a pet boar named Huffer. He wants to help you to have some fun with one of the nearby sons of Gruul.\n\nGrulloc inhabits a place known as the Cursed Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing him around, and you will retrieve the bag that he guards and deliver it to Baron Sablemane.\n\nTo get to the Cursed Hollow, head down the northern ramp and east through Dragons' End. The hollow is on the eastern edge.", sourceObjective = "Collect Grulloc's Sack.", progress = "Back so soon?  Have you come to deliver that which Rexxar owes me?", completion = "<Baron Sablemane peers inside the gronn's sack and seems satisfied.>\n\nVery well, you have upheld your end of the bargain. With that price paid, I will give Rexxar what he seeks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10722] = { id = 10722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting at the Blackwing Coven", description = "I know what must be done!  {name}, you must pose as Overseer Nuaar and attend that meeting!\n\nThe wyrmcultists at the coven all have a standard outfit that they wear, so go collect scraps from them, and when you have enough, put together a disguise.\n\nPose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has to say, and then return to Tree Warden Chawn.\n\nYou'll find the coven by heading through the Wyrmskull Tunnel and following the path past the Raven's Wood and Grishnath to its end.", sourceObjective = "Collect enough Costume Scraps from wyrmcultists to create an Overseer Disguise. Use the disguise to attend the meeting with Kolphis Darkscale.", progress = "What news do you bring?  Do you know what the wyrmcultists are up to?", completion = "Attack us?  Wipe us out?  I think not!\n\nThis Blackwing Coven has a great deal to learn if they think the Cenarion Expedition is so easily dealt with!\n\nWhat is it that they say?  Turnabout is fair play!", sourceObjectiveStatus = "unverified-source-field" }
quests[10723] = { id = 10723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom the Dragon-Eater", description = "The gronn we seek is Gorgrom the Dragon-Eater. With Sablemane's trap, you will make short work of the gronn. You will find him accepting sacrifices from the ogres of Boulder'mok.\n\nFollow the road north from the Circle of Blood, then west at Ruuan Weald. Go northwest through the tunnel.\n\nFirst, kill the ogres for their heads. We will send a message. Set the trap at his altar. When he is dead, plant the grisly totems near him - none can mistake that message.\n\nTake the bear.\n\n<Misha growls.>", sourceObjective = "Collect 3 Grisly Totems from the Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to set the trap and summon and kill Gorgrom the Dragon-Eater.\n\nWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.", progress = "The Bloodmaul ogres will trouble us no longer when this task is done.", completion = "The ogres of Bloodmaul and their master, Gorgrom, will trouble the Mok'Nathal no longer.\n\nHowever, I worry about the effect our actions will have on the other gronn. I believe we must end this fight once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10724] = { id = 10724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoner of the Bladespire", description = "Shortly after my arrival in the mountains, I came under attack by a group of Bladespire ogres.\n\nThough I fought free of them, and slew many, they took my wyvern, Leokk, captive. Spirit has found him, locked in a cage in the heart of the Bladespire encampment outside of Gruul's lair.\n\nOne of the ogres must carry his key. Find it and Spirit can use it to unlock Leokk's cage.\n\nYou will find the encampment at the north end of the Daggermaw Canyon down below.", sourceObjective = "Slay Bladespire ogres to get the Wyvern Cage Key. Once you have it, go to the Wyvern Cage and use Spirit's Whistle to summon Spirit, who will unlock the cage to free Leokk.", progress = "It will be good to have Leokk's aid once again.", completion = "Leokk has brought to us the head from one of the black dragons at Dragons' End. With this, we will be able to infuriate Goc, the gronn that captured him, and lure him into battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[10725] = { id = 10725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminence Among the Violet Eye", description = "Your services have gone above and beyond what is expected of you, {name}.  You are but a step away from achieving the highest honor available to non-citizens of Dalaran.\n\nContinue to prove your loyalty to us and I will empower your signet to its full capacity.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Exalted reputation with the Violet Eye.", progress = "Hail, {name}!  It is a great pleasure to see you once again.", completion = "The signet you now hold is as powerful as that of any Archmage of the Council.  Wear it wherever you go so that the initiated may recognize your allegiance.  Wear it wherever you go so its power may serve you as you've served us!", sourceObjectiveStatus = "unverified-source-field" }
