quests[10729] = { id = 10729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Violet Mage", sourceObjective = "Are you certain of your choice, {name}?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", sourceObjectiveStatus = "unverified-source-field" }
