quests[10737] = { id = 10737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Touch", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.", sourceObjective = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key.", sourceObjectiveStatus = "unverified-source-field" }
quests[10738] = { id = 10738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10739] = { id = 10739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10740] = { id = 10740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10741] = { id = 10741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10742] = { id = 10742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown", description = "Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.", sourceObjective = "Use Rexxar's Battle Horn at the Altar of Goc, then kill Goc.", progress = "Only through the deaths of Goc and Gorgrom the Dragon-Eater will we free the Mok'Nathal.", completion = "The battle was hard and you fought well, {name}. I am honored to have stood by your side in the battle against Goc. I am thankful beyond words.\n\nThe Mok'Nathal should know of these great defeats, but I am not ready to face them yet. I know my father's mind, and I know my heart. There is still much I can learn and do to become stronger, to show to him that I am his true son.", sourceObjectiveStatus = "unverified-source-field" }
quests[10743] = { id = 10743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "txt>Hero of the Mok'Nathal" }
quests[10744] = { id = 10744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Victory", description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.", sourceObjective = "Return to Wildhammer Stronghold and speak with Kurdran Wildhammer.", completion = "<Kurdran listens to your report.>\n\nThat is good news, indeed! Mere days ago, I wouldn't have dreamt that we could break the Legion's siege on the stronghold.\n\nNot only have you halted their offensive, but you've broken the back of their war machine as well! You have the gratitude of the Wildhammer clan for your valor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10745] = { id = 10745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Victory", description = "You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.", sourceObjective = "Return to Shadowmoon Village and speak with Overlord Or'barokh.", completion = "<The overlord listens to your report.>\n\nExcellent news! Holding the line against the Legion's infernals was taking too many resources. Not that I expected my men to break, but they were greatly strained.\n\nYou have proven your worth to the Horde this day. The Kor'kron guard would be honored to fight by your side anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[10747] = { id = 10747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelps of the Wyrmcult", description = "I need to examine the whelps that they are raising at the Blackwing Coven.\n\nThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.\n\nPlease, {name}, take the net and capture a handful of them alive for me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.", sourceObjective = "Use the Blackwhelp Net to capture 10 Wyrmcult Blackwhelps.", progress = "Did you run into much trouble snatching the whelps?  I hope you didn't get singed!", completion = "Oh my goodness, these are more than I'd hoped for!  You are certainly to be lauded for your heroics!\n\nThis looks like a fine brood of blackwhelps to make a start with.  Examining them, that is.\n\nPlease, accept this as payment.  I insist!", sourceObjectiveStatus = "unverified-source-field" }
quests[10748] = { id = 10748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxnar Must Die!", description = "They've left us no choice, {name}.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!\n\nFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.", sourceObjective = "Slay Maxnar the Ashmaw.", progress = "You've dealt with Maxnar the Ashmaw already?\n\nAre you having trouble finding him?  As I understand it if you head to the right once you enter their caverns, it will eventually curve around and lead you to him.", completion = "Now we can breathe more easily knowing that the leader of our enemy has been dealt with.  Not only that, but you've saved the entire mountain range from their depredations.\n\nWhatever their ultimate goals, you've foiled them!\n\nYou have our gratitude, {name}.  Please accept this token of our esteem, as well as our unending hospitality.", sourceObjectiveStatus = "unverified-source-field" }
quests[10749] = { id = 10749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane's Poison", description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.\n\nNow, do be a good little <boy/girl> and run this up to Rexxar.", sourceObjective = "Deliver Baron Sablemane's Poison to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "{class}, you are back so soon? Do you have the poison?", completion = "This is unsavory business, this use of poisons. But it will do what we want.", sourceObjectiveStatus = "unverified-source-field" }
quests[10750] = { id = 10750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Conquest", description = "Word has come from my wind riders, {name}. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.", sourceObjective = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", sourceObjectiveStatus = "unverified-source-field" }
quests[10751] = { id = 10751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.", sourceObjective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders.", progress = "What have you to report, soldier?", completion = "You won't believe this, grunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10752] = { id = 10752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Ashenvale", description = "Recently Raene Wolfrunner came through Auberdine from Darnassus and was heading to Ashenvale; she said something about the Furbolgs. I wasn't given an opportunity to ask more about her situation but perhaps you can seek her out and lend her your aid {class}. Take the southern road out of Auberdine. Once you reach Ashenvale border continue your path down the road. There you will find Astranaar and Raene Wolfrunner.", sourceObjective = "Speak with Raene Wolfrunner in Astranaar.", completion = "So Thundris Windweaver still thinks I need looking after? I'll need to remind him who saved whom; he seems to forget it was I that pulled him from harm's way.\n\nWell now that you're here, {race}, perhaps I can find something for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10753] = { id = 10753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Wild", description = "The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. {name}, help me stop these crimes of nature destroy all which they corrupt. \n\nOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.", sourceObjective = "Slay 4 Felsworn Scalewing, 4 Felsworn Daggermaw, and 2 Fel Corrupters.", completion = "I do not pride myself knowing we destroyed what Elune has created, but the corruption needed to be stopped. You have done well {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10754] = { id = 10754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Danath, the force commander at Honor Hold.", sourceObjective = "Bring the Primed Key Mold to Force Commander Danath at Honor Hold in Hellfire Peninsula.", progress = "You've something to show me, {name}?", completion = "Could this be?  Let me take a closer look at that mold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10755] = { id = 10755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.", sourceObjective = "Bring the Primed Key Mold to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "You've something to show me, {name}?", completion = "A key mold?  Could this be what grants us access to the Shattered Halls?", sourceObjectiveStatus = "unverified-source-field" }
quests[10756] = { id = 10756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Rohok", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.", sourceObjective = "Bring the Primed Key Mold to Rohok at Thrallmar in Hellfire Peninsula.", progress = "What is this?", completion = "Nazgrel wants me to work on a key?  Does he forget we're in a battlefield?  There are blades and spears to forge!", sourceObjectiveStatus = "unverified-source-field" }
quests[10757] = { id = 10757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohok's Request", description = "Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", sourceObjective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Rohok at Thrallmar in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Excellent.  Let's give it a shot.", sourceObjectiveStatus = "unverified-source-field" }
quests[10758] = { id = 10758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotter than Hell", description = "It's no good, {name}!  No matter how many coals I put to the fire, it's just not enough heat.\n\nThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.\n\nI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.", sourceObjective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Rohok in Thrallmar.", progress = "Did you do what I asked of you, {class}?", completion = "You've succeeded!  Only thing left for you to do is try it out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10759] = { id = 10759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Deserter", description = "I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.\n\nI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.", sourceObjective = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10760] = { id = 10760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sketh'lon Wreckage", description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.\n\nWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.", sourceObjective = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Sergeant Kargrul at Shadowmoon Village.", progress = "What have you discovered?", completion = "<The sergeant examines the journal pages.>\n\nI don't see much of use here, but there are a couple of entries that could prove useful. It looks as though these arakkoa were preparing some kind of elaborate magical ritual up until the time of their deaths, but why? There's also a curious note here about a 'deserter.'", sourceObjectiveStatus = "unverified-source-field" }
quests[10761] = { id = 10761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Deserter", description = "There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.\n\nI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him on the road through the Magma Fields to the southeast.", sourceObjective = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", sourceObjectiveStatus = "unverified-source-field" }
